#pragma once
// Importing effects: folder in the user directory (QStandardPaths::AppDataLocation/effects) where foreign
// effects are placed, plus the bundled ones (Effects Library: LUTs/gradient wipes -> Bundled/Own). So far LUTs (subfolder "LUTs", bundled as
// Qt resource ":/luts/<id>.cube") and gradient wipes (subfolder "Transitions": grayscale images as in
// Kdenlive/Shotcut/OpenShot, bundled as ":/lumas/<id>", generated by engine/Lumas). Subfolders become
// categories of the Effects Library.

#include <QString>
#include <QStringList>
#include <QVector>

namespace EffectFolders {

// Effects Library entry / drag data for a LUT: "lut:<path>" (instead of an effect id)
inline constexpr const char* LutPrefix = "lut:";

QString root();   // effects folder
QString lutDir(); // root/LUTs
QString transitionDir(); // root/Transitions (ASCII name: MLT/FFmpeg on Windows)
QString frei0rDir();     // root/frei0r: own frei0r plugins (engine/Frei0r, picked up after a restart)
QString presetDir();     // root/Presets: Shotcut/Kdenlive presets (core/Presets)
void ensure();    // create folders (and readme) if they are missing

// LUT formats (extensions lowercase, without dot): .cube, .3dl, .csp, Hald CLUT images
const QStringList& lutSuffixes();
bool isLutFile(const QString& path);
QString lutFileFilter(); // for QFileDialog

// Gradient images: grayscale (dark areas switch first), all common image formats
const QStringList& transitionSuffixes();
bool isTransitionFile(const QString& path);

struct LutEntry {
    QString path;  // file or ":/luts/<id>.cube" / ":/lumas/<id>"
    QString name;  // display
    QString group; // subfolder relative to lutDir() ("/" separated), empty = directly in the folder
};
QVector<LutEntry> builtinLuts(); // bundled, names translated
QVector<LutEntry> userLuts();    // lutDir() recursively, sorted by group and name
QVector<LutEntry> builtinTransitions(); // bundled gradient wipes
QVector<LutEntry> userTransitions();    // transitionDir() recursively
QVector<LutEntry> userPresets();        // presetDir() recursively (every file but readmes; name = file name)
QStringList watchDirs();                // LUTs/Transitions/Presets folders and all subfolders (for watching)
bool isBuiltin(const QString& path);
QString builtinId(const QString& path);  // ":/lumas/kreis" -> "kreis"
QString displayName(const QString& path); // bundled: translated name, otherwise file name (LUT) or without extension
// Project from another machine: look for a file of the same name in the LUTs or Transitions folder, empty = none
QString findUserLut(const QString& fileName);
QString findUserTransition(const QString& fileName);

} // namespace EffectFolders
